// Paper III.d: pause on probing, spending near the cap, or a burst to new sellers.
const out = [];
for (const { json: a } of $input.all()) {
  const reasons = [];
  if (Number(a.rejected_5m) >= 3) reasons.push(`${a.rejected_5m} refused calls in 5 minutes`);
  if (Number(a.funded_5m) > 0 && Number(a.spent_today) >= 0.9 * Number(a.daily_cap)) {
    reasons.push(`spent ${a.spent_today} of the ${a.daily_cap} USDC daily cap`);
  }
  if (Number(a.new_seller_funds_5m) >= 3) reasons.push(`${a.new_seller_funds_5m} jobs funded to new sellers at once`);
  if (reasons.length) out.push({ json: { ...a, reasons } });
}
return out; // empty = nothing to do, the workflow stops here

// Demo: one guardian credential (the buyer's). For more owners, add signers per owner.
return $input.all().map(({ json: a }) => ({ json: {
  signer: 'guardian-buyer', method: 'pause', args: { owner: a.owner_id },
  ownerId: a.owner_id, jobId: null, amount: null,
} }));

