return $('Rules').all().map(({ json: a }, k) => {
  const tx = $('Chain call').all()[k]?.json || {};
  const message = tx.ok
    ? `Paused your agents: ${a.reasons.join('; ')}. Only you can unpause.`
    : `Tried to pause your agents (${a.reasons.join('; ')}) but the call failed: ${tx.error}`;
  return { json: {
    runId: 'guardian-' + Date.now(), ownerId: a.owner_id, agentId: a.guardian_id, jobId: null,
    actorLabel: 'Guardian', message, severity: 'block',
    data: { reasons: a.reasons, pauseTx: tx.txHash || null },
    notify: { runId: 'guardian-' + Date.now(), role: 'guardian', ok: Boolean(tx.ok), jobId: null,
              result: { ownerId: a.owner_id, reasons: a.reasons, pauseTx: tx.txHash || null }, error: tx.error || null },
  } };
});
